// Settings -> object (client concierge bot, AI-guarded defaults).
// The Telegram bot secret is no longer read from Settings at all: transport runs entirely through n8n Credentials.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def){ if (v === undefined || v === '') return def; return String(v).toLowerCase() === 'true' || v === '1'; }
function num(v, def){ const n = Number(v); return Number.isFinite(n) ? n : def; }
const cfg = {
  owner_chat_id: settings.owner_chat_id || '551662084',
  timezone: settings.timezone || 'Europe/Chisinau',
  lead_intake_webhook_url: settings.lead_intake_webhook_url || 'https://ghennadi.app.n8n.cloud/webhook/finmentor-lead-intake',
  website_url: settings.website_url || 'https://finmentor.md',
  default_language: (settings.default_language || 'ru').toLowerCase(),
  bot_enabled: bool(settings.bot_enabled, true),
  client_ai_enabled: bool(settings.client_ai_enabled, false),
  client_ai_model: settings.client_ai_model || 'PASTE_AI_MODEL_PLACEHOLDER_HERE',
  client_ai_temperature: num(settings.client_ai_temperature, 0.2)
};
return [{ json: { settings: cfg } }];

// Parse Telegram Update (client bot). Trigger отдаёт update на верхнем уровне (или в .body).
const u = $('Telegram Client Trigger').first().json;
const update = u.body || u;
const cb = update.callback_query || null;
const msg = update.message || update.edited_message || null;

let chat_id='', user_id='', username='', first_name='', last_name='', language='', message_text='', callback_data='', callback_query_id='';
if (cb) {
  chat_id = String(cb.message && cb.message.chat ? cb.message.chat.id : '');
  user_id = String(cb.from ? cb.from.id : '');
  username = (cb.from && cb.from.username) || '';
  first_name = (cb.from && cb.from.first_name) || '';
  last_name = (cb.from && cb.from.last_name) || '';
  language = (cb.from && cb.from.language_code) || '';
  callback_data = cb.data || '';
  callback_query_id = cb.id || '';
} else if (msg) {
  chat_id = String(msg.chat ? msg.chat.id : '');
  user_id = String(msg.from ? msg.from.id : '');
  username = (msg.from && msg.from.username) || '';
  first_name = (msg.from && msg.from.first_name) || '';
  last_name = (msg.from && msg.from.last_name) || '';
  language = (msg.from && msg.from.language_code) || '';
  message_text = msg.text || '';
}
if (!chat_id) return [];  // служебный апдейт без чата — игнор
return [{ json: {
  chat_id, user_id, username, first_name, last_name, language,
  message_text, callback_data, callback_query_id,
  is_callback: !!cb,
  raw_update: JSON.stringify(update).slice(0, 4000)
}}];

// Build Bot Response — FINMENTOR PREMIUM RU Concierge.
